// Edit these values once. Other nodes read them from here.
return [
  {
    json: {
      // Discord channel > Edit Channel > Integrations > Webhooks > Copy Webhook URL
      discordWebhookUrl: 'PASTE_YOUR_DISCORD_WEBHOOK_URL_HERE',
      // MLB team ID. 121 is the New York Mets.
      teamId: 121,
      timezone: 'America/New_York',
    },
  },
];

const { teamId } = $('Settings').first().json;
const games = ($json.dates ?? []).flatMap((d) => d.games);

// Remember which games were already posted. Static data is saved only
// for production (active) runs, so manual test runs can post again.
const memory = $getWorkflowStaticData('global');
memory.posted = memory.posted ?? [];

const out = [];
for (const game of games) {
  if (game.status.abstractGameState !== 'Final') continue;
  if (game.status.detailedState === 'Postponed') continue;
  if (memory.posted.includes(game.gamePk)) continue;

  const home = game.teams.home;
  const away = game.teams.away;
  const mets = home.team.id === teamId ? home : away;
  const opp = home.team.id === teamId ? away : home;
  const won = mets.score > opp.score;
  const inning = game.linescore?.currentInning;
  const extras = inning && inning > 9 ? ` (${inning} inn.)` : '';

  const wp = game.decisions?.winner?.fullName;
  const lp = game.decisions?.loser?.fullName;
  const sv = game.decisions?.save?.fullName;
  const decisions = [wp && `W: ${wp}`, lp && `L: ${lp}`, sv && `SV: ${sv}`]
    .filter(Boolean)
    .join(' | ');

  const header = won ? '✅ **METS WIN!** 🎉' : '❌ **Mets lose.** We get them next time.';
  const score = `Mets ${mets.score}, ${opp.team.name} ${opp.score}${extras}`;
  const record = mets.leagueRecord ? `Record: ${mets.leagueRecord.wins}-${mets.leagueRecord.losses}` : '';

  out.push({ json: { message: [header, score, decisions, record].filter(Boolean).join('\n') } });
  memory.posted.push(game.gamePk);
}

// Keep the list short.
memory.posted = memory.posted.slice(-50);

return out;
